def count_weak_quartets_cliques(n, k, a):
    if k * a > n:
        return 0
    X = a * (a - 1) // 2
    return k * X * ( (n - a) * (n - a - 1) // 2 - (k - 1) * X )

def count_weak_quartets_single_clique(n, a):
    X = a * (a - 1) // 2
    return X * (n - a) * (n - a - 1) // 2

def count_weak_quartets_matching(n):
    m = n // 2
    return m * ( (n - 2) * (n - 3) // 2 - (m - 1) )

